<template><div class="login"><section class="brand"><router-link to="/" class="logo"><img src="../../../assets/img/transparent-logo1.png"><span>SOPHOR<small>TECHNOLOGIES PLC</small></span></router-link><div><label>SECURE TEAM ACCESS</label><h1>Good work starts with <em>great systems.</em></h1><p>Sign in to the Sophor Technologies administration workspace.</p></div><small>ENGINEERING DIGITAL PROGRESS · © {{year}} SOPHOR TECHNOLOGIES PLC</small></section><section class="panel"><div><router-link to="/" class="back">← Back to website</router-link><label>ADMINISTRATOR PORTAL</label><h2>Welcome back.</h2><p>Enter your authorized staff credentials to continue.</p><form @submit.prevent="signIn"><label>Email address<input v-model="form.email" type="email" required autocomplete="username" placeholder="name@sophortechnologies.com"></label><label>Password<input v-model="form.password" type="password" required autocomplete="current-password" placeholder="Enter your password"></label><p v-if="error" class="error">{{error}}</p><button :disabled="loading">{{loading?'Signing in…':'Sign in securely'}} →</button></form><p class="help">Need access? <a href="mailto:info@sophortechnologies.com?subject=Staff%20access%20request">Request an account from your administrator.</a></p><small class="secure">♢ Protected access for authorized Sophor staff</small></div></section></div></template><script>export default{name:'LoginPage',data(){return{year:new Date().getFullYear(),form:{email:'',password:''},error:'',loading:false}},methods:{async signIn(){this.error='';this.loading=true;try{const r=await this.$apiPost('/auth/login',{...this.form});localStorage.setItem('access',r.accessToken);localStorage.setItem('refresh',r.refreshToken);localStorage.setItem('userId',r.id);localStorage.setItem('email',r.email);localStorage.setItem('name',r.name);localStorage.setItem('owner_id',r.owner_id??'');localStorage.setItem('roles',JSON.stringify(r.roles?.map(x=>x.name)||[]));localStorage.setItem('permissions',JSON.stringify(r.permissions||[]));this.$router.push('/dashboard/first-dash')}catch(e){this.error=e.response?.data?.message||'Unable to sign in. Check your credentials or contact your administrator.'}finally{this.loading=false}}}}</script><style scoped>.login{min-height:100vh;background:#f4f7fc;display:grid;place-items:center;padding:25px}.login>section{min-height:620px}.login{grid-template-columns:minmax(0,480px) minmax(0,480px);justify-content:center}.brand{background:#0b192d;color:white;padding:40px;display:flex;flex-direction:column;justify-content:space-between;border-radius:12px 0 0 12px}.logo{display:flex;align-items:center;gap:10px;color:white;font-size:14px;font-weight:900;letter-spacing:.1em}.logo img{width:42px;height:42px;object-fit:contain}.logo small{display:block;font-size:7px;color:#8ea5c4;margin-top:4px}.brand label,.panel>div>label{font-size:9px;letter-spacing:.2em;color:#70a4ff;font-weight:900}.brand h1{font-size:45px;line-height:1.1;letter-spacing:-.05em;margin:17px 0}.brand em{font-style:normal;color:#76a8ff}.brand p{font-size:12px;color:#aab8cb;line-height:1.8}.brand>small{font-size:8px;color:#8398b6;letter-spacing:.1em}.panel{background:white;padding:45px;display:grid;place-items:center;border-radius:0 12px 12px 0;box-shadow:0 25px 80px #10243d12}.panel>div{width:100%;max-width:340px}.back{display:block;font-size:10px;color:#78869a;margin-bottom:55px}.panel h2{font-size:30px;margin:10px 0 4px}.panel p{font-size:11px;color:#78869a}.panel form{display:grid;gap:17px;margin-top:30px}.panel form label{font-size:10px;font-weight:800;color:#34445a;display:grid;gap:8px}.panel input{padding:13px;border:1px solid #dce4ef;border-radius:5px;font-size:11px}.panel button{background:#2868f5;color:white;border:0;padding:14px;border-radius:5px;text-align:left;font-size:11px;font-weight:900}.panel button:disabled{opacity:.6}.help{margin-top:22px;line-height:1.8}.help a{color:#2868f5;font-weight:800}.secure{display:block;margin-top:38px;color:#8795a8;font-size:9px}.error{background:#fff0f0;color:#b33b3b;padding:10px;border-radius:5px}@media(max-width:760px){.login{display:block;padding:0}.login>section{min-height:auto}.brand{border-radius:0;padding:30px}.brand h1{font-size:33px}.brand>div:nth-child(2){margin:35px 0}.panel{border-radius:0;padding:40px 25px;min-height:500px}.back{margin-bottom:35px}}</style>